 BufferedImage atlas=ImageIO.read(new File("../koios-cache/arpg-art/biome-maps-v1.png"));check(atlas!=null&&atlas.getColorModel().hasAlpha(),"Biome atlas retains transparency");check(atlas.getWidth()>=1024&&atlas.getHeight()>=512,"Source resolution preserves painterly detail");int middle=atlas.getWidth()/2;for(int y=0;y<atlas.getHeight();y++)for(int x=middle-8;x<middle+8;x++)check((atlas.getRGB(x,y)>>>24)<80,"Transparent gutter separates map cells");for(int cell=0;cell<2;cell++){int first=cell*middle,last=(cell+1)*middle;int opaque=0,minX=99999,maxX=-1,minY=99999,maxY=-1;for(int y=0;y<atlas.getHeight();y++)for(int x=first;x<last;x++)if((atlas.getRGB(x,y)>>>24)>=220){opaque++;minX=Math.min(minX,x-first);maxX=Math.max(maxX,x-first);minY=Math.min(minY,y);maxY=Math.max(maxY,y);}check(opaque>10000,"Cell has illustrated map "+cell);check(minX>=3&&maxX<middle-3&&minY>=3&&maxY<atlas.getHeight()-3,"Whole illustration has transparent edge gutters "+cell);}
 int[] ids={22410,22413,22414};Set<Integer> hashes=new HashSet<>();com.koios.client.graphic.ImageProducer surface=new com.koios.client.graphic.ImageProducer(200,80);Arrays.fill(surface.canvasRaster,0x141B22);for(int i=0;i<ids.length;i++){Sprite icon=ArtSprites.icon(ids[i]);check(icon!=null&&icon.highResolutionArt!=null,"Actual map ID resolves retained art "+ids[i]);check(icon.highResolutionArt.getWidth()==128&&icon.highResolutionArt.getHeight()==128,"Map source retained128px "+ids[i]);check(hashes.add(Arrays.hashCode(icon.myPixels)),"Three distinct map illustrations "+ids[i]);check(icon.myPixels[0]==0&&icon.myPixels[31]==0&&icon.myPixels[992]==0&&icon.myPixels[1023]==0,"Inventory corners transparent "+ids[i]);check((icon.highResolutionArt.getRGB(0,0)>>>24)==0,"Highres transparent corner "+ids[i]);icon.drawSprite(16+i*60,18);}
